function mergeParity(target: Record<string, any>, source: Record<string, any>) {
  for (const [key, value] of Object.entries(source)) {
    if (
      value &&
      typeof value === "object" &&
      !Array.isArray(value) &&
      target[key] &&
      typeof target[key] === "object" &&
      !Array.isArray(target[key])
    ) {
      mergeParity(target[key], value);
    } else if (
      value &&
      typeof value === "object" &&
      !Array.isArray(value) &&
      (!target[key] || typeof target[key] !== "object" || Array.isArray(target[key]))
    ) {
      target[key] = {};
      mergeParity(target[key], value);
    } else if (target[key] === undefined) {
      target[key] = value;
    }
  }
}

mergeParity(en as Record<string, any>, parityPatch);

export default en;
